from openpyxl import load_workbook
from math import isclose
p='/root/nasa_budget_recovered.xlsx'
wb=load_workbook(p, data_only=False)
missing=[]
errors=[]
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for cell in row:
            if cell.value == '???': missing.append(f'{ws.title}!{cell.coordinate}')
            if isinstance(cell.value,str) and cell.value.startswith('#'): errors.append(f'{ws.title}!{cell.coordinate}={cell.value}')
b=wb['Budget by Directorate']; y=wb['YoY Changes (%)']; s=wb['Directorate Shares (%)']; g=wb['Growth Analysis']
for row in range(4,14):
    if sum(b.cell(row,col).value for col in range(2,11)) != b.cell(row,11).value:
        errors.append(f'Budget total mismatch row {row}')
for row in range(5,13):
    for col in range(2,12):
        current=b.cell(row,col).value; previous=b.cell(row-1,col).value
        actual=round((current/previous-1)*100,2)
        shown=y.cell(row-1,col).value
        if actual != shown: errors.append(f'YoY mismatch {y.cell(row-1,col).coordinate}: {shown} vs {actual}')
for row in range(4,14):
    total=b.cell(row,11).value
    for col in range(2,11):
        actual=round(b.cell(row,col).value/total*100,2)
        shown=s.cell(row,col).value
        if actual != shown: errors.append(f'Share mismatch {s.cell(row,col).coordinate}: {shown} vs {actual}')
checks={
 'E4':round(((7618/5047)**(1/5)-1)*100,2), 'E5':5047,
 'B7':8440-6906, 'B8':round(sum([6906,7139,7301,7614,8262,8440])/6,1),
}
for cell, expected in checks.items():
    if g[cell].value != expected: errors.append(f'Growth mismatch {cell}: {g[cell].value} vs {expected}')
print('missing:', missing)
print('errors:', errors)
print('verified replacements:', sum(1 for ws in wb.worksheets for row in ws.iter_rows() for c in row if c.value is not None))
